descriptor.templateCss:
.turbine-mimic {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-width: 320px;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  overflow: hidden;
  position: relative;
  background: #0f172a;
}
.tm-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 14px;
  background: #090d16;
  border-bottom: 1px solid #1e293b;
}
.tm-title {
  font-size: 15px;
  font-weight: 700;
  color: #f8fafc;
  letter-spacing: 0.5px;
}
.tm-kpi-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 6px;
  padding: 8px 10px 10px;
  flex: 0 0 260px;
  overflow-y: auto;
  align-content: start;
  background: #090d16;
  border-left: 1px solid #1e293b;
}
.tm-kpi-tile {
  border: 1px solid #334155;
  border-radius: 6px;
  padding: 5px 8px;
  background: #1e293b;
}
.tm-kpi-tile.tm-state-warning { border-color: #f59e0b; background: rgba(245, 158, 11, 0.12); }
.tm-kpi-tile.tm-state-alarm { border-color: #ef4444; background: rgba(239, 68, 68, 0.15); }
.tm-kpi-tile.tm-state-down { border-color: #64748b; background: rgba(100, 116, 139, 0.15); }

.tm-kpi-label {
  font-size: 10px;
  font-weight: 600;
  color: #94a3b8;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.tm-kpi-value {
  font-size: 16px;
  font-weight: 700;
  color: #38bdf8;
}
.tm-kpi-unit {
  font-size: 10px;
  font-weight: 600;
  color: #64748b;
  margin-left: 3px;
}





















.tm-state-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.tm-state-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
}

/* Colour is always paired with the text label above/icon — decision 17:
   never rely on hue alone. */
.state-healthy .tm-state-dot, .tm-state-chip.state-healthy .tm-state-dot { background: #2e7d32; }
.state-healthy, .tm-state-chip.state-healthy { background: rgba(46,125,50,0.12); color: #1b5e20; }

.state-warning .tm-state-dot, .tm-state-chip.state-warning .tm-state-dot { background: #f9a825; }
.state-warning, .tm-state-chip.state-warning { background: rgba(249,168,37,0.15); color: #8d6e00; }

.state-alarm .tm-state-dot, .tm-state-chip.state-alarm .tm-state-dot { background: #c62828; }
.state-alarm, .tm-state-chip.state-alarm { background: rgba(198,40,40,0.15); color: #b71c1c; }

.state-down .tm-state-dot, .tm-state-chip.state-down .tm-state-dot { background: #757575; }
.state-down, .tm-state-chip.state-down { background: rgba(117,117,117,0.15); color: #424242; }

.tm-diagram-wrap {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;

  /* Phase 3 fleet-view optimisation. The schematic is ~250 SVG nodes; on a
     fleet board most instances are below the fold, and the browser was
     laying out and painting every one of them on load.

     content-visibility:auto tells the browser to skip rendering work for
     the subtree while it is off-screen and do it when it scrolls in --
     the "lazy-load the SVG only when in viewport" idea, but implemented by
     the engine rather than by an IntersectionObserver, so there is no
     JS to run, nothing to tear down, and no risk of the schematic
     failing to appear if a callback is missed. Browsers without support
     ignore both declarations and render exactly as before.

     contain-intrinsic-size supplies a placeholder size for the skipped
     subtree, without which the page would collapse and then jump as each
     widget scrolls in. 320px is the schematic's rendered height at the
     6x5 grid cell the fleet dashboard uses. */
  content-visibility: auto;
  contain-intrinsic-size: auto 320px;
}

#tm-svg-root {
  width: 100%;
  height: 100%;
  display: block;
}

/* Runtime state-colour modifiers ("tm-state-*", distinct from the SVG's own
   static "state-*" classes so the widget's toggle logic never fights the
   SVG's initial healthy styling) toggled onto a .hotspot <g> by
   applyHotspotState() in onDataUpdated(). Cascades onto the actual painted
   shape (.component-box, or the rotor casing <polygon>, which shares
   that class) via a descendant selector so the controller only ever has to
   touch one element's classList per hotspot. */
.hotspot.tm-state-warning .component-box { fill: #fff8e1; stroke: #f9a825; stroke-width: 2.5; }
.hotspot.tm-state-alarm .component-box { fill: #fdecea; stroke: #c62828; stroke-width: 2.5; animation: tm-pulse 1.1s ease-in-out infinite; }
.hotspot.tm-state-down .component-box { fill: #eceff1; stroke: #607d8b; stroke-dasharray: 4 3; }

@keyframes tm-pulse {
  0%   { opacity: 1; }
  50%  { opacity: 0.55; }
  100% { opacity: 1; }
}

/* Rotor rotation: the controller sets an SVG transform="rotate(<deg> 605
   175)" presentation attribute directly on #rotor-blades every tick (the
   rotation origin (605,175) is the documented hub centre in SVG user-space
   coordinates -- see the "Rotor element" comment inline in the SVG above),
   rather than a CSS custom property, because the production art rotates
   only the blade/hub subgroup, not the whole turbine casing. */
#rotor-blades {
  transition: transform 0.95s linear;
}

.turbine-mimic.state-down #tm-svg-root {
  filter: grayscale(1);
}

.tm-down-banner {
  position: absolute;
  top: 8px;
  left: 8px;
  right: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  background: rgba(66,66,66,0.9);
  color: #fff;
  border-radius: 4px;
  font-size: 13px;
}









/* --- Phase 3: alert pulsing -------------------------------------------
   Production ops scan a wall of tiles, so the pulse has to be noticeable
   in peripheral vision without being the thing you fight to read past.
   Two deliberate choices:

   1. The pulse animates box-shadow (a ring OUTSIDE the tile), not opacity
      of the tile itself. Fading a tile in and out makes its NUMBER hard to
      read at exactly the moment the number matters most. The ring leaves
      the text at full contrast throughout.
   2. Warning and critical differ in rate as well as hue -- 2.4s versus
      1.4s -- so the severity survives greyscale, a mono display, and the
      ~8% of male operators with a red/green colour deficiency. Colour is
      never the only channel (the tile also carries a text status in its
      tooltip and a border-colour change).

   The alarm ring peaks at 0.55 alpha rather than 1.0: an 8-tile alarm
   cascade at full strength reads as a strobe, which is the "jarring"
   failure mode this is explicitly meant to avoid. */
@keyframes tm-tile-pulse-warning {
  0%, 100% { box-shadow: 0 0 0 0 rgba(249,168,37,0.00); }
  50%      { box-shadow: 0 0 0 3px rgba(249,168,37,0.35); }
}

@keyframes tm-tile-pulse-alarm {
  0%, 100% { box-shadow: 0 0 0 0 rgba(198,40,40,0.00); }
  50%      { box-shadow: 0 0 0 4px rgba(198,40,40,0.55); }
}




/* A stale tile is a known-unknown, not an emergency: it must not compete
   with a live alarm for attention, so it stays completely still. */


/* Vestibular safety, and a genuine ops preference on always-on wall
   displays: honour the OS "reduce motion" setting by dropping to a static
   ring that still encodes severity by colour and width. */
@media (prefers-reduced-motion: reduce) {
  .tm-kpi-tile.tm-state-warning,
  .tm-kpi-tile.tm-state-alarm,
  .hotspot.tm-state-alarm .component-box {
    animation: none;
  }


}

/* --- Phase 3: hover/focus tooltip ------------------------------------- */


.tm-kpi-tile:focus-visible {
  outline: 2px solid #1976d2;
  outline-offset: 1px;
}

.tm-tooltip {
  position: absolute;
  z-index: 20;
  min-width: 200px;
  max-width: 280px;
  padding: 8px 10px;
  border-radius: 6px;
  background: rgba(23,33,46,0.97);
  color: #f5f7fa;
  font-size: 12px;
  line-height: 1.45;
  box-shadow: 0 4px 14px rgba(0,0,0,0.35);
  pointer-events: none;
}

.tm-tt-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 4px;
}

.tm-tt-label { font-weight: 600; }

.tm-tt-status {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 1px 5px;
  border-radius: 3px;
  white-space: nowrap;
}

.tm-tt-status.tm-tt-ok { background: rgba(46,125,50,0.30); color: #a5d6a7; }
.tm-tt-status.tm-tt-warning { background: rgba(249,168,37,0.30); color: #ffe082; }
.tm-tt-status.tm-tt-critical { background: rgba(198,40,40,0.35); color: #ef9a9a; }
.tm-tt-status.tm-tt-stale { background: rgba(158,158,158,0.30); color: #e0e0e0; }
.tm-tt-status.tm-tt-none { background: rgba(120,144,156,0.30); color: #cfd8dc; }

.tm-tt-reading { margin-bottom: 5px; }
.tm-tt-value { font-size: 18px; font-weight: 600; }
.tm-tt-unit { font-size: 11px; opacity: 0.75; margin-left: 3px; }
.tm-tt-pct { font-size: 11px; opacity: 0.75; margin-left: 6px; }

.tm-tt-bands { margin-bottom: 4px; }

.tm-tt-band-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  opacity: 0.92;
}

.tm-tt-swatch {
  width: 9px;
  height: 9px;
  border-radius: 2px;
  flex: 0 0 auto;
}

.tm-tt-swatch.tm-tt-sw-ok { background: #66bb6a; }
.tm-tt-swatch.tm-tt-sw-warn { background: #f9a825; }
.tm-tt-swatch.tm-tt-sw-crit { background: #e53935; }

.tm-tt-age, .tm-tt-note { font-size: 11px; opacity: 0.7; }
.tm-tt-note { margin-top: 3px; font-style: italic; }







.tm-kpi-icon {
  font-size: 12px;
  margin-right: 4px;
}

/* Mobile: 960x540 desktop schematic collapses to a stacked 600px-min layout.
   Thingsboard mobile app renders the widget inside a narrow webview, so this
   media query is the practical trigger rather than a device check. */
@media (max-width: 700px) {

  .tm-diagram-wrap { min-height: 220px; }


}

descriptor.controllerScript:
self.onInit = function () {

  // Hide and remove ThingsBoard footer globally
  (function hideThingsboardFooter() {
    if (!document.getElementById('tb-hide-powered-by')) {
      var s = document.createElement('style');
      s.id = 'tb-hide-powered-by';
      s.textContent = '.tb-powered-by-footer, section[data-html2canvas-ignore].tb-powered-by-footer, section.tb-powered-by-footer, a[href*="thingsboard.io"] { display: none !important; visibility: hidden !important; height: 0 !important; width: 0 !important; opacity: 0 !important; pointer-events: none !important; }';
      document.head.appendChild(s);
    }
    var f = document.querySelector('.tb-powered-by-footer');
    if (f) { f.style.display = 'none'; f.remove(); }
    if (!window.__tbFooterObserverSet) {
      window.__tbFooterObserverSet = true;
      var obs = new MutationObserver(function() {
        var el = document.querySelector('.tb-powered-by-footer');
        if (el) { el.style.display = 'none'; el.remove(); }
      });
      obs.observe(document.documentElement, { childList: true, subtree: true });
    }
  })();

  var settings = self.ctx.settings || {};

  // Configurable, never hardcoded: falls back to Phase 0 defaults reconciled
  // from app/config/anomaly_thresholds.json, but every value here can be
  // overridden per-widget-instance in the dashboard editor so the same
  // widget type serves any customer/site/turbine and any future threshold
  // change without a code edit.
  self.ctx.maxRpm = Number(settings.maxRpm) || 14000; // RAMP_UP critical_max, anomaly_thresholds.json
  self.ctx.staleThresholdSeconds = Number(settings.staleThresholdSeconds) || 120; // matches STATE_STALE_SECONDS default
  // MERGE, not replace. A dashboard's settings.thresholds overrides the
  // built-in band for the keys it names and leaves every other key on the
  // default.
  //
  // This was a real defect, found in a live browser: the Turbine Schematic
  // dashboard carried a Phase 1 settings.thresholds listing only four
  // sensors. Because that object is truthy, `settings.thresholds ||
  // DEFAULT_THRESHOLDS` selected it wholesale and the other eight headline
  // KPIs silently lost their bands -- no colour, no alarm, no tooltip
  // range, on a dashboard that looked completely normal. Re-introducing
  // through configuration exactly the "7 of 12 tiles cannot signal a
  // fault" gap Phase 3 set out to close.
  //
  // Per-key merge makes a partial override do the obviously-intended
  // thing, and makes the failure mode of a stale dashboard config
  // "one sensor uses an old band" rather than "most sensors have none".
  self.ctx.thresholds = mergeThresholds(DEFAULT_THRESHOLDS, settings.thresholds);
  self.ctx.kpiOrder = settings.kpiOrder || DEFAULT_KPI_ORDER;

  self.ctx.container = self.ctx.$container ? self.ctx.$container[0] : null;
  self.ctx.svgRoot = self.ctx.container ? self.ctx.container.querySelector('#tm-svg-root') : null;
  // Two distinct elements in the production SVG (app/visualization/turbine-schematic.svg):
  // #hotspot-rotor is the static turbine casing <polygon> -- it only ever gets
  // a state-colour class toggled on it, never rotates. #rotor-blades is the
  // nested <g> that actually spins (rotation origin (605,175), see the SVG's
  // own "Rotor element" comment).
  self.ctx.rotorHotspotEl = self.ctx.container ? self.ctx.container.querySelector('#hotspot-rotor') : null;
  self.ctx.rotorBladesEl = self.ctx.container ? self.ctx.container.querySelector('#rotor-blades') : null;
  self.ctx.kpiGridEl = self.ctx.container ? self.ctx.container.querySelector('#tm-kpi-grid') : null;
  self.ctx.downBannerEl = self.ctx.container ? self.ctx.container.querySelector('#tm-down-banner') : null;
  self.ctx.downTextEl = self.ctx.container ? self.ctx.container.querySelector('#tm-down-text') : null;
  self.ctx.titleEl = self.ctx.container ? self.ctx.container.querySelector('#tm-title') : null;
  self.ctx.stateChipEl = self.ctx.container ? self.ctx.container.querySelector('#tm-state-chip') : null;
  self.ctx.stateTextEl = self.ctx.container ? self.ctx.container.querySelector('#tm-state-text') : null;

  if (self.ctx.titleEl) {
    self.ctx.titleEl.textContent = settings.title || (self.ctx.widgetTitle || 'Turbine');
  }
  if (self.ctx.downTextEl) {
    self.ctx.downTextEl.textContent =
      'NO DATA — turbine reporting stale (>' + self.ctx.staleThresholdSeconds + 's)';
  }

  // Phase 3 tooltip nodes. One shared popover reused by all 12 tiles.
  self.ctx.tooltipEl = self.ctx.container ? self.ctx.container.querySelector('#tm-tooltip') : null;
  self.ctx.tooltipEls = self.ctx.container ? {
    label:  self.ctx.container.querySelector('#tm-tt-label'),
    status: self.ctx.container.querySelector('#tm-tt-status'),
    value:  self.ctx.container.querySelector('#tm-tt-value'),
    unit:   self.ctx.container.querySelector('#tm-tt-unit'),
    pct:    self.ctx.container.querySelector('#tm-tt-pct'),
    bands:  self.ctx.container.querySelector('#tm-tt-bands'),
    age:    self.ctx.container.querySelector('#tm-tt-age'),
    note:   self.ctx.container.querySelector('#tm-tt-note')
  } : {};
  // Which dataKey the popover is currently describing, or null when hidden.
  // Also the flag that lets onDataUpdated() skip all tooltip work while
  // nobody is hovering, which is the common case.
  self.ctx.activeTooltipKey = null;

  self.ctx.cumulativeRotorDeg = 0;
  self.ctx.isStale = false;
  self.ctx.overallState = 'healthy';
  self.ctx.overallStateLabel = 'Healthy';

  self.ctx.kpiTileEls = {};
  // Last value/state actually written to each tile's DOM. renderKpiGrid()
  // compares against this and skips the write when nothing changed --
  // see the PERFORMANCE note on renderKpiGrid().
  self.ctx.kpiRendered = {};
  // Most recent sample per key, kept so the tooltip can report a real
  // "last updated" age without re-walking ctx.data on every mouse move.
  self.ctx.latestByKey = {};
  // Memoised resolveBand() results, keyed "<dataKey>|<state>". The band for
  // a given key and operating state never changes between ticks, so
  // resolving it once per state transition instead of 12x per second is
  // free correctness-wise and removes the table walk from the hot path.
  self.ctx.bandCache = {};

  // Render counters, read by app/tools/profile_widget_dashboard.py and by
  // the performance tests. Counting DOM writes rather than timing them is
  // what makes the optimisation measurable in CI, where wall-clock timings
  // are too noisy to assert on.
  self.ctx.perf = { ticks: 0, tileWrites: 0, tileSkips: 0, lastTickMs: 0 };
  // Expose the counter object (by reference -- it is mutated in place, never
  // reassigned) on the widget root so an out-of-process profiler can read
  // real render costs out of a live browser session instead of estimating
  // them. See app/tools/profile_widget_dashboard.py.
  if (self.ctx.container) {
    self.ctx.container.__tmPerf = self.ctx.perf;
  }
};

self.onDataUpdated = function () {
  var tickStart = Date.now();
  var latest = readLatestValues(self.ctx);
  var nowMs = tickStart;

  // The turbine's own operating state selects which threshold band applies
  // (see DEFAULT_THRESHOLDS). Supplied by the `state` dataKey; when the
  // dashboard's datasource omits it, resolveBand() falls back to
  // STEADY_STATE.
  var stateSample = latest.state;
  var newState =
    stateSample && stateSample.value ? String(stateSample.value) : DEFAULT_STATE;
  if (newState !== self.ctx.operatingState) {
    // Bands are per-state, so a state change is the only thing that can
    // invalidate the memo.
    self.ctx.bandCache = {};
    self.ctx.operatingState = newState;
  }

  self.ctx.latestByKey = latest;

  renderStaleness(self.ctx, latest, nowMs);
  renderRotor(self.ctx, latest);
  renderKpiGrid(self.ctx, latest, nowMs);
  renderOverallState(self.ctx, latest);

  // Only repaint the popover when one is actually open. With no hover this
  // costs a single null check per tick rather than 12 string builds.
  if (self.ctx.activeTooltipKey) {
    updateTooltipContent(self.ctx, self.ctx.activeTooltipKey, nowMs);
  }

  self.ctx.perf.ticks += 1;
  self.ctx.perf.lastTickMs = Date.now() - tickStart;

  if (self.ctx.detectChanges) {
    self.ctx.detectChanges();
  }
};

self.onResize = function () {
  // SVG uses viewBox + preserveAspectRatio, so it reflows on its own; nothing
  // to recompute here beyond letting the browser relayout the flex grid.
};

self.onDestroy = function () {
  // Detach the per-tile listeners bound in bindTileInteractions() before
  // dropping the element refs. Thingsboard reuses a dashboard's DOM when
  // an operator switches states/time windows, so leaking a listener per
  // tile per instance is exactly the leak that shows up as a fleet board
  // getting slower the longer it is left open.
  var keys = Object.keys(self.ctx.kpiTileEls || {});
  for (var i = 0; i < keys.length; i++) {
    var tile = self.ctx.kpiTileEls[keys[i]];
    if (tile && tile._tmHandlers && tile.removeEventListener) {
      tile.removeEventListener('mouseenter', tile._tmHandlers.enter);
      tile.removeEventListener('mouseleave', tile._tmHandlers.leave);
      tile.removeEventListener('focus', tile._tmHandlers.enter);
      tile.removeEventListener('blur', tile._tmHandlers.leave);
      tile._tmHandlers = null;
    }
  }

  self.ctx.container = null;
  self.ctx.svgRoot = null;
  self.ctx.rotorHotspotEl = null;
  self.ctx.rotorBladesEl = null;
  self.ctx.kpiGridEl = null;
  self.ctx.downBannerEl = null;
  self.ctx.tooltipEl = null;
  self.ctx.tooltipEls = {};
  self.ctx.activeTooltipKey = null;
  self.ctx.kpiTileEls = {};
  self.ctx.kpiRendered = {};
  self.ctx.latestByKey = {};
  self.ctx.bandCache = {};
};

self.typeParameters = function () {
  return {
    maxDatasources: 1,
    maxDataKeys: -1, // any number of dataKeys — the widget renders whatever the dashboard binds
    singleEntity: true,
    hasDataPageLink: false,
    defaultDataKeysFunction: function () {
      return DEFAULT_KPI_ORDER.map(function (key) {
        return { name: key, label: key, type: 'timeseries' };
      });
    }
  };
};

// -----------------------------------------------------------------------
// Helpers (still inside controllerScript — Thingsboard evaluates the whole
// descriptor.controllerScript string in one scope, so top-level `function`
// and `const` declarations here are visible to self.onInit/onDataUpdated).
// -----------------------------------------------------------------------

// Phase 0-reconciled headline sensors (data/turbine-schema-extracted.json).
var DEFAULT_KPI_ORDER = [
  'TURBINE_SPEED_RPM', 'GB_TRQ', 'PYRO_T', 'PYRO_GB',
  'PT_109A', 'FT_110A', 'PT_150A',
  'XT_600', 'XT_601', 'XT_604', 'XT_605', 'ZT_600'
];

// `valId` is the matching <text id="val-*"> element in the inlined SVG
// (app/visualization/turbine-schematic.svg) that onDataUpdated() writes the
// live number into, in addition to the always-present tile below the
// diagram built by renderKpiGrid().
var KPI_META = {
  TURBINE_SPEED_RPM: { label: 'Speed', unit: 'rpm', icon: '↻', valId: 'val-turbine-speed' },
  GB_TRQ:            { label: 'GB Torque', unit: 'kN·m', icon: '⚙', valId: 'val-gb-torque' },
  PYRO_T:            { label: 'Pyro Temp (Turbine)', unit: '°C', icon: '☀', valId: 'val-pyro-t' },
  PYRO_GB:           { label: 'Pyro Temp (Gearbox)', unit: '°C', icon: '☀', valId: 'val-pyro-gb' },
  PT_109A:           { label: 'Inlet Pressure A', unit: 'bar', icon: '●', valId: 'val-inlet-pressure' },
  FT_110A:           { label: 'Main Water Flow', unit: 'TPH', icon: '≈', valId: 'val-inlet-flow' },
  PT_150A:           { label: 'Hydraulic Pressure A', unit: 'kg/cm²', icon: '●', valId: 'val-hydraulic-pressure' },
  XT_600:            { label: 'GB Vibration X', unit: 'mm/s', icon: '⤳', valId: 'val-vib-gb-x' },
  XT_601:            { label: 'GB Vibration Y', unit: 'mm/s', icon: '⤳', valId: 'val-vib-gb-y' },
  XT_604:            { label: 'Rotor Vibration X', unit: 'mm/s', icon: '⤳', valId: 'val-vib-rotor-x' },
  XT_605:            { label: 'Rotor Vibration Y', unit: 'mm/s', icon: '⤳', valId: 'val-vib-rotor-y' },
  ZT_600:            { label: 'GB Vibration Z1', unit: 'mm/s', icon: '⤳', valId: 'val-vib-gb-z1' }
};

// State-aware thresholds (per operating state: IDLE, RAMP_UP, STEADY_STATE, RAMP_DOWN).
var DEFAULT_STATE = 'STEADY_STATE';

var DEFAULT_THRESHOLDS = {
  TURBINE_SPEED_RPM: {
    IDLE:         { warningMin: -50, warningMax: 300, criticalMin: -100, criticalMax: 600 },
    RAMP_UP:      { warningMin: 1000, warningMax: 12000, criticalMin: 100, criticalMax: 14000 },
    STEADY_STATE: { warningMin: 11500, warningMax: 12000, criticalMin: 10500, criticalMax: 12800 },
    RAMP_DOWN:    { warningMin: 1000, warningMax: 11000, criticalMin: 100, criticalMax: 12500 }
  },
  GB_TRQ: {
